// Clean the submitted keywords before paying for them:
// lowercase, single spaces, no duplicates, no keyword the Actor would refuse (over 80 characters or 10 words),
// and skip keywords already checked in the sheet (rows tagged "no data" are checked again).
const norm = (s) => String(s ?? '').normalize('NFKC').toLowerCase().replace(/\s+/g, ' ').trim();
const submitted = String($('Submit keywords').first().json['Keywords'] ?? '').split(/[\n,;]+/);
const saved = new Set($('Read saved keywords').all()
  .filter((i) => i.json.tier !== 'no data')
  .map((i) => norm(i.json.keyword)).filter(Boolean));

const seen = new Set();
const keywords = [];
let duplicates = 0;
let alreadySaved = 0;
let tooLong = 0;
for (const raw of submitted) {
  const keyword = norm(raw);
  if (!keyword) continue;
  if (seen.has(keyword)) { duplicates++; continue; }
  seen.add(keyword);
  if (keyword.length > 80 || keyword.split(' ').length > 10) { tooLong++; continue; }
  if (saved.has(keyword)) { alreadySaved++; continue; }
  keywords.push(keyword);
}
// Nothing new: end here without calling Apify (nothing billed).
if (keywords.length === 0) return [];
return [{ json: { keywords, duplicates, alreadySaved, tooLong } }];

// Opportunity score from 0 to 100 = volume points + ease points + value points.
//   Volume (max 40): 8 points per power of ten -> 100 searches = 16, 1,000 = 24, 10,000 = 32, 100,000+ = 40.
//   Ease   (max 40): (100 - keyword difficulty) x 0.4 -> difficulty 10 = 36, 50 = 20, 90 = 4. Unknown = 20.
//   Value  (max 20): CPC in USD x 4 -> $1 = 4, $2.50 = 10, $5 or more = 20 (advertisers pay for buyers).
// Quick win = at least minVolume searches a month AND difficulty at most maxDifficulty.
const s = $('Settings').first().json;
const minVolume = Number(s.minVolume ?? 100);
const maxDifficulty = Number(s.maxDifficulty ?? 30);
const goodScore = Number(s.goodScore ?? 50);
const norm = (k) => String(k ?? '').normalize('NFKC').toLowerCase().replace(/\s+/g, ' ').trim();
const saved = new Set($('Read saved keywords').all()
  .filter((i) => i.json.tier !== 'no data')
  .map((i) => norm(i.json.keyword)).filter(Boolean));
const savedNoData = new Set($('Read saved keywords').all()
  .filter((i) => i.json.tier === 'no data')
  .map((i) => norm(i.json.keyword)).filter(Boolean));
// Rows the Actor did not look up (free-plan limits): not written, so they are checked on a later run.
const notLookedUp = /^(Not looked up|Nothing was looked up|Free Apify plan)/;
const today = new Date().toISOString().slice(0, 10);

const seen = new Set();
const rows = [];
for (const { json: k } of $input.all()) {
  const keyword = norm(k.keyword);
  if (!keyword || seen.has(keyword) || saved.has(keyword)) continue;
  if (k.found === false && notLookedUp.test(k.note ?? '')) continue;
  seen.add(keyword);
  // Already in the sheet as "no data" and still without data: not written twice.
  if (k.found === false && savedNoData.has(keyword)) continue;
  // Same columns on every row, in the order of the sheet header.
  const row = (tier, opportunityScore, why, m = {}) => ({
    keyword, tier, opportunityScore, why,
    searchVolume: m.searchVolume ?? null, keywordDifficulty: m.keywordDifficulty ?? null, cpcUsd: m.cpcUsd ?? null,
    competitionLevel: m.competitionLevel ?? null, searchIntent: m.searchIntent ?? null, trendYearlyPct: m.trendYearlyPct ?? null,
    country: k.country ?? s.country, checkedAt: today,
  });
  if (k.found === false) {
    rows.push(row('no data', null, k.note || 'No Google data for this keyword (not billed)'));
    continue;
  }
  const volume = Number(k.searchVolume) || 0;
  const kd = k.keywordDifficulty ?? null;
  const cpc = Number(k.cpcUsd) || 0;
  const volumePts = Math.round(Math.min(40, Math.max(0, 8 * Math.log10(Math.max(volume, 1)))));
  const easePts = kd == null ? 20 : Math.round((100 - kd) * 0.4);
  const valuePts = Math.round(Math.min(20, cpc * 4));
  const score = volumePts + easePts + valuePts;
  const quickWin = volume >= minVolume && kd != null && kd <= maxDifficulty;
  const why = `${volume.toLocaleString('en-US')} searches/mo (+${volumePts}), ` +
    `difficulty ${kd ?? 'unknown'} (+${easePts}), CPC $${cpc.toFixed(2)} (+${valuePts})`;
  rows.push(row(quickWin ? 'quick win' : score >= goodScore ? 'worth a look' : 'low priority', score, why, k));
}
// Best first: quick wins first, even below goodScore; then by score; keywords without data at the end.
const order = { 'quick win': 0, 'worth a look': 1, 'low priority': 2, 'no data': 3 };
rows.sort((a, b) => order[a.tier] - order[b.tier] || (b.opportunityScore ?? -1) - (a.opportunityScore ?? -1));
return rows.map((r, i) => ({ json: { batchRank: i + 1, ...r } }));

// One Slack message with the best quick wins. No quick win: no message.
const s = $('Settings').first().json;
const rows = $input.all().map((i) => i.json);
const scored = rows.filter((r) => r.tier !== 'no data').length;
const wins = rows.filter((r) => r.tier === 'quick win');
if (wins.length === 0) return [];
// Keywords the free Apify plan did not look up (not written to the sheet, same test as in Score opportunities).
const notLookedUp = /^(Not looked up|Nothing was looked up|Free Apify plan)/;
const notChecked = $('Get volume, CPC and difficulty').all()
  .filter((i) => i.json.found === false && notLookedUp.test(i.json.note ?? '')).length;
const skipped = notChecked > 0 ? `, ${notChecked} not checked (free Apify plan): submit them again later` : '';
const top = Number(s.slackTopN) || 10;
const lines = wins.slice(0, top).map((r, i) =>
  `${i + 1}. *${r.keyword}*: score ${r.opportunityScore}, ${Number(r.searchVolume || 0).toLocaleString('en-US')} searches/mo, ` +
  `difficulty ${r.keywordDifficulty}, CPC $${Number(r.cpcUsd || 0).toFixed(2)}${r.searchIntent ? `, ${r.searchIntent}` : ''}`);
const more = wins.length > top ? `\n…and ${wins.length - top} more in the sheet.` : '';
return [{ json: {
  text: `:rocket: *${wins.length} keyword quick win${wins.length > 1 ? 's' : ''}* in ${s.country} ` +
    `(${scored} new keywords scored${skipped}; difficulty ≤ ${s.maxDifficulty}, ${s.minVolume}+ searches/mo)\n\n` +
    lines.join('\n') + more,
  quickWins: wins.length,
} }];
